import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"Agent Skill","description":"","frontmatter":{},"headers":[],"relativePath":"developers/skill.md","filePath":"developers/skill.md","lastUpdated":1792570296000}'),o={name:"developers/skill.md"};function i(s,e,l,d,c,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="agent-skill" tabindex="-1">Agent Skill <a class="header-anchor" href="#agent-skill" aria-label="Permalink to &quot;Agent Skill&quot;">​</a></h1><p>Use PaperSeek from an agent that supports Skills and can run local commands. The Skill guides the agent through installation checks, configuration, literature searches, and reading saved results.</p><p>Searches run in your local Community installation. History and artifacts stay in its local storage; model and source requests use the services you configure. No PaperSeek account is required.</p><h2 id="add-the-skill" tabindex="-1">Add the Skill <a class="header-anchor" href="#add-the-skill" aria-label="Permalink to &quot;Add the Skill&quot;">​</a></h2><p>The Skill lives at <a href="https://github.com/paperseek/paperseek/tree/main/integrations/skills/paperseek" target="_blank" rel="noreferrer">integrations/skills/paperseek</a> in the repository.</p><ol><li>Use your agent&#39;s Skill installer to add that directory, or copy the complete <code>paperseek</code> folder into the project or user Skill directory documented by your client.</li><li>Keep <code>SKILL.md</code> and the <code>references/</code> directory together. The references contain installation steps and the supported command and source options.</li><li>Reload the client&#39;s Skills if required, then check that it recognizes the name <strong>paperseek</strong>.</li></ol><p>You can add the Skill before installing Community. Copying the Skill itself does not install Python, PaperSeek, or model credentials.</p><h2 id="first-use" tabindex="-1">First use <a class="header-anchor" href="#first-use" aria-label="Permalink to &quot;First use&quot;">​</a></h2><p>Ask your agent to use PaperSeek for a concrete research question:</p><blockquote><p>Use the PaperSeek Skill to find literature on how open-source funding affects software maintenance. Check the local installation first; if PaperSeek is missing, install it in an isolated environment and check the configuration. Search OpenAlex, save the run, and summarize relevant papers with source links.</p></blockquote><p>The Skill guides the agent to:</p><ol><li><strong>Check the installation.</strong> Locate <code>paperseek</code>, inspect its version, and reuse an existing environment or executable path.</li><li><strong>Install if needed.</strong> Use Python 3.12+ and an isolated environment. An agent with execution permissions can perform the installation; otherwise it provides the steps for you.</li><li><strong>Check configuration.</strong> Run <code>paperseek doctor --json</code> without a live search. Resolve missing required model or source settings first.</li><li><strong>Search locally.</strong> Select the source, submit the question through the Community CLI, and retain the run ID, status, warnings, and results.</li></ol><p>An existing installation is not automatically upgraded, and its data is not automatically migrated. For a version change, follow the <a href="./../self-hosting/upgrade">upgrade guide</a>.</p><h2 id="configure-models-and-sources" tabindex="-1">Configure models and sources <a class="header-anchor" href="#configure-models-and-sources" aria-label="Permalink to &quot;Configure models and sources&quot;">​</a></h2><p>Provide your model connection and source credentials through the local process environment or your agent client&#39;s private environment settings. The Skill uses the same <code>PAPERSEEK_*</code> settings as Community. See <a href="./../reference/configuration">configuration</a>, <a href="./../guide/models">models</a>, and <a href="./../guide/sources">data sources</a>.</p><p>Do not put real keys in a conversation, <code>SKILL.md</code>, or committed client settings. If a required value is missing, the agent should report its name and guide you to configure it locally.</p><p>The CLI reads its process environment. Values entered only in the Web form do not automatically configure a separate agent process, and an <code>.env</code> file is not loaded automatically by the CLI.</p><h2 id="continue-a-research-task" tabindex="-1">Continue a research task <a class="header-anchor" href="#continue-a-research-task" aria-label="Permalink to &quot;Continue a research task&quot;">​</a></h2><p>You can ask the agent to inspect a saved run, summarize warnings, retrieve normalized paper metadata, or help export results. For interactive filtering, history, and citation maps, open the local Web workspace using the same database.</p><p>For example:</p><blockquote><p>Open the saved PaperSeek run we just created. Show its status and source, summarize the most relevant papers, and help me export the results as CSV.</p></blockquote><p>PaperSeek relevance scores help screen literature; check the original studies before relying on a generated synthesis. This Skill does not automatically read paper PDFs or perform a complete systematic review.</p><h2 id="skill-mcp-or-http-api" tabindex="-1">Skill, MCP, or HTTP API? <a class="header-anchor" href="#skill-mcp-or-http-api" aria-label="Permalink to &quot;Skill, MCP, or HTTP API?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Entry point</th><th>Use it when</th></tr></thead><tbody><tr><td><strong>Agent Skill</strong></td><td>Your agent can run local commands and needs guidance on installing and using PaperSeek</td></tr><tr><td><a href="./mcp">MCP</a></td><td>Your assistant uses structured tools for starting, inspecting, cancelling, and exporting searches</td></tr><tr><td><a href="./api">HTTP API</a></td><td>You are building an application against the running PaperSeek server</td></tr></tbody></table><p>The Skill works through the CLI without installing MCP or starting a Web server. It can also guide an agent to use an existing local API or matched MCP integration when appropriate. See the <a href="./cli">CLI guide</a> for the underlying commands.</p>',25)])])}const g=t(o,[["render",i]]);export{p as __pageData,g as default};
